using Xunit;

public class U17_GUITest
{
    [Fact]
    public void TestPatientPressureDisplay()
    {
        // Arrange
        var controller = new Mock<IController>();
        controller.Setup(c => c.GetPatientPressure()).Returns(50);

        // Act
        var gui = new GUI(controller.Object);

        // Assert
        Assert.Equal(50, gui.PatientPressure);
    }

    [Fact]
    public void TestGraphRefreshRate()
    {
        // Arrange
        var gui = new GUI(new Mock<IController>().Object);

        // Act
        gui.RefreshGraph();

        // Assert
        Assert.True(gui.GraphRefreshRate >= 20);
    }

    // ... remaining test cases for other requirements ...
}
